/* Lei seca da Revisão — redação oficial, sem texto autoral. Gerado por scripts/build-lei-revisao.mjs. */
(function(g){g.BC_LEI_REVISAO=g.BC_LEI_REVISAO||{};g.BC_LEI_REVISAO["adm"]=g.BC_LEI_REVISAO["adm"]||{};g.BC_LEI_REVISAO["adm"][13]=[{"key":"l8429:9","law":"l8429","ref":"9","label":"Lei de Improbidade Administrativa · Art. 9","paragraphs":["Art. 9º Constitui ato de improbidade administrativa importando em enriquecimento ilícito auferir, mediante a prática de ato doloso, qualquer tipo de vantagem patrimonial indevida em razão do exercício de cargo, de mandato, de função, de emprego ou de atividade nas entidades referidas no art. 1º desta Lei, e notadamente: (“Caput” do artigo com redação dada pela Lei nº 14.230, de 25/10/2021)","I - receber, para si ou para outrem, dinheiro, bem móvel ou imóvel, ou qualquer outra vantagem econômica, direta ou indireta, a título de comissão, percentagem, gratificação ou presente de quem tenha interesse, direto ou indireto, que possa ser atingido ou amparado por ação ou omissão decorrente das atribuições do agente público;","II - perceber vantagem econômica, direta ou indireta, para facilitar a aquisição, permuta ou locação de bem móvel ou imóvel, ou a contratação de serviços pelas entidades referidas no art. 1 º por preço superior ao valor de mercado;","III - perceber vantagem econômica, direta ou indireta, para facilitar a alienação, permuta ou locação de bem público ou o fornecimento de serviço por ente estatal por preço inferior ao valor de mercado;","IV - utilizar, em obra ou serviço particular, qualquer bem móvel, de propriedade ou à disposição de qualquer das entidades referidas no art. 1º desta Lei, bem como o trabalho de servidores, de empregados ou de terceiros contratados por essas entidades; ( Incis o com redação dada pela Lei nº 14.230, de 25/10/2021)","V - receber vantagem econômica de qualquer natureza, direta ou indireta, para tolerar a exploração ou a prática de jogos de azar, de lenocínio, de narcotráfico, de contrabando, de usura ou de qualquer outra atividade ilícita, ou aceitar promessa de tal vantagem;","VI - receber vantagem econômica de qualquer natureza, direta ou indireta, para fazer declaração falsa sobre qualquer dado técnico que envolva obras públicas ou qualquer outro serviço ou sobre quantidade, peso, medida, qualidade ou característica de mercadorias ou bens fornecidos a qualquer das entidades referidas no art. 1º desta Lei; ( Incis o com redação dada pela Lei nº 14.230, de 25/10/2021)","VII - adquirir, para si ou para outrem, no exercício de mandato, de cargo, de emprego ou de função pública, e em razão deles, bens de qualquer natureza, decorrentes dos atos descritos no caput deste artigo, cujo valor seja desproporcional à evolução do patrimônio ou à renda do agente público, assegurada a demonstração pelo agente da licitude da origem dessa evolução; ( Incis o com redação dada pela Lei nº 14.230, de 25/10/2021)","VIII - aceitar emprego, comissão ou exercer atividade de consultoria ou assessoramento para pessoa física ou jurídica que tenha interesse suscetível de ser atingido ou amparado por ação ou omissão decorrente das atribuições do agente público, durante a atividade;","IX - perceber vantagem econômica para intermediar a liberação ou aplicação de verba pública de qualquer natureza;","X - receber vantagem econômica de qualquer natureza, direta ou indiretamente, para omitir ato de ofício, providência ou declaração a que esteja obrigado;","XI - incorporar, por qualquer forma, ao seu patrimônio bens, rendas, verbas ou valores integrantes do acervo patrimonial das entidades mencionadas no art. 1 º desta Lei;","XII - usar, em proveito próprio, bens, rendas, verbas ou valores integrantes do acervo patrimonial das entidades mencionadas no art. 1 º desta Lei."],"url":""},{"key":"l8429:11","law":"l8429","ref":"11","label":"Lei de Improbidade Administrativa · Art. 11","paragraphs":["Art. 11. Constitui ato de improbidade administrativa que atenta contra os princípios da administração pública a ação ou omissão dolosa que viole os deveres de honestidade, de imparcialidade e de legalidade, caracterizada por uma das seguintes condutas: (“Caput” do artigo com redação dada pela Lei nº 14.230, de 25/10/2021)","I - ( Revogado pela Lei nº 14.230, de 25/10/2021)","II - ( Revogado pela Lei nº 14.230, de 25/10/2021)","III - revelar fato ou circunstância de que tem ciência em razão das atribuições e que deva permanecer em segredo, propiciando beneficiamento por informação privilegiada ou colocando em risco a segurança da sociedade e do Estado; ( Incis o com redação dada pela Lei nº 14.230, de 25/10/2021)","IV - negar publicidade aos atos oficiais, exceto em razão de sua imprescindibilidade para a segurança da sociedade e do Estado ou de outras hipóteses instituídas em lei; ( Incis o com redação dada pela Lei nº 14.230, de 25/10/2021)","V - frustrar, em ofensa à imparcialidade, o caráter concorrencial de concurso público, de chamamento ou de procedimento licitatório, com vistas à obtenção de benefício próprio, direto ou indireto, ou de terceiros; ( Incis o com redação dada pela Lei nº 14.230, de 25/10/2021)","VI - deixar de prestar contas quando esteja obrigado a fazê-lo, desde que disponha das condições para isso, com vistas a ocultar irregularidades; ( Incis o com redação dada pela Lei nº 14.230, de 25/10/2021)","VII - revelar ou permitir que chegue ao conhecimento de terceiro, antes da respectiva divulgação oficial, teor de medida política ou econômica capaz de afetar o preço de mercadoria, bem ou serviço ;","VIII - descumprir as normas relativas à celebração, fiscalização e aprovação de contas de parcerias firmadas pela administração pública com entidades privadas ; ( Inciso acrescido pela Lei nº 13.019, de 31/7/2014 , publicada no DOU de 1/8/2014, em vigor 540 dias após a publicação )","IX - ( Inciso acrescido pela Lei nº 13.146, de 6/7/2015 , e revogado pela Lei nº 14.230, de 25/10/2021)","X - (Inciso acrescido pela Lei nº 13.650, de 11/4/2018 , e revogado pela Lei nº 14.230, de 25/10/2021)","XI - nomear cônjuge, companheiro ou parente em linha reta, colateral ou por afinidade, até o terceiro grau, inclusive, da autoridade nomeante ou de servidor da mesma pessoa jurídica investido em cargo de direção, chefia ou assessoramento, para o exercício de cargo em comissão ou de confiança ou, ainda, de função gratificada na administração pública direta e indireta em qualquer dos Poderes da União, dos Estados, do Distrito Federal e dos Municípios, compreendido o ajuste mediante designações recíprocas; ( Incis o acrescido pela Lei nº 14.230, de 25/10/2021)","XII - praticar, no âmbito da administração pública e com recursos do erário, ato de publicidade que contrarie o disposto no § 1º do art. 37 da Constituição Federal, de forma a promover inequívoco enaltecimento do agente público e personalização de atos, de programas, de obras, de serviços ou de campanhas dos órgãos públicos. ( Incis o acrescido pela Lei nº 14.230, de 25/10/2021)","§ 1º Nos termos da Convenção das Nações Unidas contra a Corrupção, promulgada pelo Decreto nº 5.687, de 31 de janeiro de 2006, somente haverá improbidade administrativa, na aplicação deste artigo, quando for comprovado na conduta funcional do agente público o fim de obter proveito ou benefício indevido para si ou para outra pessoa ou entidade. ( Parágraf o acrescido pela Lei nº 14.230, de 25/10/2021)","§ 2º Aplica-se o disposto no § 1º deste artigo a quaisquer atos de improbidade administrativa tipificados nesta Lei e em leis especiais e a quaisquer outros tipos especiais de improbidade administrativa instituídos por lei. ( Parágraf o acrescido pela Lei nº 14.230, de 25/10/2021)","§ 3º O enquadramento de conduta funcional na categoria de que trata este artigo pressupõe a demonstração objetiva da prática de ilegalidade no exercício da função pública, com a indicação das normas constitucionais, legais ou infralegais violadas. ( Parágraf o acrescido pela Lei nº 14.230, de 25/10/2021)","§ 4º Os atos de improbidade de que trata este artigo exigem lesividade relevante ao bem jurídico tutelado para serem passíveis de sancionamento e independem do reconhecimento da produção de danos ao erário e de enriquecimento ilícito dos agentes públicos. ( Parágraf o acrescido pela Lei nº 14.230, de 25/10/2021)","§ 5º Não se configurará improbidade a mera nomeação ou indicação política por parte dos detentores de mandatos eletivos, sendo necessária a aferição de dolo com finalidade ilícita por parte do agente. ( Parágraf o acrescido pela Lei nº 14.230, de 25/10/2021)"],"url":""},{"key":"l8429:10","law":"l8429","ref":"10","label":"Lei de Improbidade Administrativa · Art. 10","paragraphs":["Art. 10. Constitui ato de improbidade administrativa que causa lesão ao erário qualquer ação ou omissão dolosa, que enseje, efetiva e comprovadamente, perda patrimonial, desvio, apropriação, malbaratamento ou dilapidação dos bens ou haveres das entidades referidas no art. 1º desta Lei, e notadamente: (“Caput” do artigo com redação dada pela Lei nº 14.230, de 25/10/2021)","I - facilitar ou concorrer, por qualquer forma, para a indevida incorporação ao patrimônio particular, de pessoa física ou jurídica, de bens, de rendas, de verbas ou de valores integrantes do acervo patrimonial das entidades referidas no art. 1º desta Lei; ( Incis o com redação dada pela Lei nº 14.230, de 25/10/2021)","II - permitir ou concorrer para que pessoa física ou jurídica privada utilize bens, rendas, verbas ou valores integrantes do acervo patrimonial das entidades mencionadas no art. 1º desta Lei, sem a observância das formalidades legais ou regulamentares aplicáveis à espécie;","III - doar à pessoa física ou jurídica bem como ao ente despersonalizado, ainda que de fins educativos ou assistências, bens, rendas, verbas ou valores do patrimônio de qualquer das entidades mencionadas no art. 1º desta Lei, sem observância das formalidades legais e regulamentares aplicáveis à espécie;","IV - permitir ou facilitar a alienação, permuta ou locação de bem integrante do patrimônio de qualquer das entidades referidas no art. 1º desta Lei, ou ainda a prestação de serviço por parte delas, por preço inferior ao de mercado;","V - permitir ou facilitar a aquisição, permuta ou locação de bem ou serviço por preço superior ao de mercado;","VI - realizar operação financeira sem observância das normas legais e regulamentares ou aceitar garantia insuficiente ou inidônea;","VII - conceder benefício administrativo ou fiscal sem a observância das formalidades legais ou regulamentares aplicáveis à espécie;","VIII - frustrar a licitude de processo licitatório ou de processo seletivo para celebração de parcerias com entidades sem fins lucrativos, ou dispensá-los indevidamente, acarretando perda patrimonial efetiva; ( Incis o com redação dada pela Lei nº 14.230, de 25/10/2021)","IX - ordenar ou permitir a realização de despesas não autorizadas em lei ou regulamento;","X - agir ilicitamente na arrecadação de tributo ou de renda, bem como no que diz respeito à conservação do patrimônio público; ( Incis o com redação dada pela Lei nº 14.230, de 25/10/2021)","XI - liberar verba pública sem a estrita observância das normas pertinentes ou influir de qualquer forma para a sua aplicação irregular;","XII - permitir, facilitar ou concorrer para que terceiro se enriqueça ilicitamente;","XIII - permitir que se utilize, em obra ou serviço particular, veículos, máquinas, equipamentos ou material de qualquer natureza, de propriedade ou à disposição de qualquer das entidades mencionadas no art. 1 º desta Lei, bem como o trabalho de servidor público, empregados ou terceiros contratados por essas entidades.","XIV - celebrar contrato ou outro instrumento que tenha por objeto a prestação de serviços públicos por meio da gestão associada sem observar as formalidades previstas na lei; (Inciso acrescido pela Lei nº 11.107, de 6/4/2005)","XV - celebrar contrato de rateio de consórcio público sem suficiente e prévia dotação orçamentária, ou sem observar as formalidades previstas na lei. (Inciso acrescido pela Lei nº 11.107, de 6/4/2005)","XVI - facilitar ou concorrer, por qualquer forma, para a incorporação, ao patrimônio particular de pessoa física ou jurídica, de bens, rendas, verbas ou valores públicos transferidos pela administração pública a entidades privadas mediante celebração de parcerias, sem a observância das formalidades legais ou regulamentares aplicáveis à espécie; ( Inciso acrescido pela Lei nº 13.019, de 31/7/2014 , publicada no DOU de 1/8/2014, em vigor 540 dias após a publicação )","XVII - permitir ou concorrer para que pessoa física ou jurídica privada utilize bens, rendas, verbas ou valores públicos transferidos pela administração pública a entidade privada mediante celebração de parcerias, sem a observância das formalidades legais ou regulamentares aplicáveis à espécie; ( Inciso acrescido pela Lei nº 13.019, de 31/7/2014 , publicada no DOU de 1/8/2014, em vigor 540 dias após a publicação )","XVIII - celebrar parcerias da administração pública com entidades privadas sem a observância das formalidades legais ou regulamentares aplicáveis à espécie; ( Inciso acrescido pela Lei nº 13.019, de 31/7/2014 , publicada no DOU de 1/8/2014, em vigor 540 dias após a publicação )","XIX - agir para a configuração de ilícito na celebração, na fiscalização e na análise das prestações de contas de parcerias firmadas pela administração pública com entidades privadas; ( Inciso acrescido pela Lei nº 13.019, de 31/7/2014 , e com nova redação dada pela Lei nº 14.230, de 25/10/2021)","XX - liberar recursos de parcerias firmadas pela administração pública com entidades privadas sem a estrita observância das normas pertinentes ou influir de qualquer forma para a sua aplicação irregular. ( Inciso acrescido pela Lei nº 13.019, de 31/7/2014 , publicada no DOU de 1/8/2014, em vigor 540 dias após a publicação , com redação dada pela Lei nº 13.204, de 14/12/2015)","XXI - ( Inciso acrescido pela Lei nº 13.019, de 31/7/2014 , e revogado pela Lei nº 14.230, de 25/10/2021)","XXII - conceder, aplicar ou manter benefício financeiro ou tributário contrário ao que dispõem o caput e o § 1º do art. 8º-A da Lei Complementar nº 116, de 31 de julho de 2003. (Inciso acrescido pela Lei nº 14.230, de 25/10/2021)","§ 1º Nos casos em que a inobservância de formalidades legais ou regulamentares não implicar perda patrimonial efetiva, não ocorrerá imposição de ressarcimento, vedado o enriquecimento sem causa das entidades referidas no art. 1º desta Lei. (Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 2º A mera perda patrimonial decorrente da atividade econômica não acarretará improbidade administrativa, salvo se comprovado ato doloso praticado com essa finalidade. (Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)"],"url":""},{"key":"l8429:10-A","law":"l8429","ref":"10-A","label":"Lei de Improbidade Administrativa · Art. 10-A","paragraphs":["Art. 10-A. ( Artigo acrescido pela Lei Complementar nº 157, de 29/12/2016 , e revogado pela Lei nº 14.230, de 25/10/2021)"],"url":""},{"key":"cf:37","law":"cf","ref":"37","label":"Constituição Federal · CF/88 · Art. 37","paragraphs":["Art. 37. A administração pública direta e indireta de qualquer dos Poderes da União, dos Estados, do Distrito Federal e dos Municípios obedecerá aos princípios de legalidade, impessoalidade, moralidade, publicidade e eficiência e, também, ao seguinte: (“Caput” do artigo com redação dada pela Emenda Constitucional nº 19, de 1998)","I - os cargos, empregos e funções públicas são acessíveis aos brasileiros que preencham os requisitos estabelecidos em lei, assim como aos estrangeiros, na forma da lei; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","II - a investidura em cargo ou emprego público depende de aprovação prévia em concurso público de provas ou de provas e títulos, de acordo com a natureza e a complexidade do cargo ou emprego, na forma prevista em lei, ressalvadas as nomeações para cargo em comissão declarado em lei de livre nomeação e exoneração; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","III - o prazo de validade do concurso público será de até dois anos, prorrogável uma vez, por igual período;","IV - durante o prazo improrrogável previsto no edital de convocação, aquele aprovado em concurso público de provas ou de provas e títulos será convocado com prioridade sobre novos concursados para assumir cargo ou emprego, na carreira;","V - as funções de confiança, exercidas exclusivamente por servidores ocupantes de cargo efetivo, e os cargos em comissão, a serem preenchidos por servidores de carreira nos casos, condições e percentuais mínimos previstos em lei, destinam-se apenas às atribuições de direção, chefia e assessoramento; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","VI - é garantido ao servidor público civil o direito à livre associação sindical;","VII - o direito de greve será exercido nos termos e nos limites definidos em lei específica; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","VIII - a lei reservará percentual dos cargos e empregos públicos para as pessoas portadoras de deficiência e definirá os critérios de sua admissão;","IX - a lei estabelecerá os casos de contratação por tempo determinado para atender a necessidade temporária de excepcional interesse público;","X - a remuneração dos servidores públicos e o subsídio de que trata o § 4º do art. 39 somente poderão ser fixados ou alterados por lei específica, observada a iniciativa privativa em cada caso, assegurada revisão geral anual, sempre na mesma data e sem distinção de índices; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XI - a remuneração e o subsídio dos ocupantes de cargos, funções e empregos públicos da administração direta, autárquica e fundacional, dos membros de qualquer dos Poderes da União, dos Estados, do Distrito Federal e dos Municípios, dos detentores de mandato eletivo e dos demais agentes políticos e os proventos, pensões ou outra espécie remuneratória, percebidos cumulativamente ou não, incluídas as vantagens pessoais ou de qualquer outra natureza, não poderão exceder o subsídio mensal, em espécie, dos Ministros do Supremo Tribunal Federal, aplicando-se como limite, nos Municípios, o subsídio do Prefeito, e nos Estados e no Distrito Federal, o subsídio mensal do Governador no âmbito do Poder Executivo, o subsídio dos Deputados Estaduais e Distritais no âmbito do Poder Legislativo e o subsídio dos Desembargadores do Tribunal de Justiça, limitado a noventa inteiros e vinte e cinco centésimos por cento do subsídio mensal, em espécie, dos Ministros do Supremo Tribunal Federal, no âmbito do Poder Judiciário, aplicável este limite aos membros do Ministério Público, aos Procuradores e aos Defensores Públicos; (Inciso com redação dada pela Emenda Constitucional nº 41, de 2003)","XII - os vencimentos dos cargos do Poder Legislativo e do Poder Judiciário não poderão ser superiores aos pagos pelo Poder Executivo;","XIII - é vedada a vinculação ou equiparação de quaisquer espécies remuneratórias para o efeito de remuneração de pessoal do serviço público; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XIV - os acréscimos pecuniários percebidos por servidor público não serão computados nem acumulados para fins de concessão de acréscimos ulteriores; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XV - o subsídio e os vencimentos dos ocupantes de cargos e empregos públicos são irredutíveis, ressalvado o disposto nos incisos XI e XIV deste artigo e nos arts. 39, § 4º, 150, II, 153, III, e 153, § 2º, I; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XVI - é vedada a acumulação remunerada de cargos públicos, exceto, quando houver compatibilidade de horários, observado em qualquer caso o disposto no inciso XI: (“Caput” do inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","a) a de dois cargos de professor;","b) a de um cargo de professor com outro de qualquer natureza; (Alínea com redação dada pela Emenda Constitucional nº 138, de 2025)","c) a de dois cargos ou empregos privativos de profissionais de saúde, com profissões regulamentadas; (Alínea com redação dada pela Emenda Constitucional nº 34, de 2001)","XVII - a proibição de acumular estende-se a empregos e funções e abrange autarquias, fundações, empresas públicas, sociedades de economia mista, suas subsidiárias, e sociedades controladas, direta ou indiretamente, pelo poder público; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XVIII - a administração fazendária e seus servidores fiscais terão, dentro de suas áreas de competência e jurisdição, precedência sobre os demais setores administrativos, na forma da lei;","XIX - somente por lei específica poderá ser criada autarquia e autorizada a instituição de empresa pública, de sociedade de economia mista e de fundação, cabendo à lei complementar, neste último caso, definir as áreas de sua atuação; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XX - depende de autorização legislativa, em cada caso, a criação de subsidiárias das entidades mencionadas no inciso anterior, assim como a participação de qualquer delas em empresa privada;","XXI - ressalvados os casos especificados na legislação, as obras, serviços, compras e alienações serão contratados mediante processo de licitação pública que assegure igualdade de condições a todos os concorrentes, com cláusulas que estabeleçam obrigações de pagamento, mantidas as condições efetivas da proposta, nos termos da lei, o qual somente permitirá as exigências de qualificação técnica e econômica indispensáveis à garantia do cumprimento das obrigações.","XXII - as administrações tributárias da União, dos Estados, do Distrito Federal e dos Municípios, atividades essenciais ao funcionamento do Estado, exercidas por servidores de carreiras específicas, terão recursos prioritários para a realização de suas atividades e atuarão de forma integrada, inclusive com o compartilhamento de cadastros e de informações fiscais, na forma da lei ou convênio. (Inciso acrescido pela Emenda Constitucional nº 42, de 2003)","§ 1º A publicidade dos atos, programas, obras, serviços e campanhas dos órgãos públicos deverá ter caráter educativo, informativo ou de orientação social, dela não podendo constar nomes, símbolos ou imagens que caracterizem promoção pessoal de autoridades ou servidores públicos.","§ 2º A não-observância do disposto nos incisos II e III implicará a nulidade do ato e a punição da autoridade responsável, nos termos da lei.","§ 3º A lei disciplinará as formas de participação do usuário na administração pública direta e indireta, regulando especialmente:","I - as reclamações relativas à prestação dos serviços públicos em geral, asseguradas a manutenção de serviços de atendimento ao usuário e a avaliação periódica, externa e interna, da qualidade dos serviços;","II - o acesso dos usuários a registros administrativos e a informações sobre atos de governo, observado o disposto no art. 5º, X e XXXIII;","III - a disciplina da representação contra o exercício negligente ou abusivo de cargo, emprego ou função na administração pública. (Parágrafo com redação dada pela Emenda Constitucional nº 19, de 1998)","§ 4º Os atos de improbidade administrativa importarão a suspensão dos direitos políticos, a perda da função pública, a indisponibilidade dos bens e o ressarcimento ao erário, na forma e gradação previstas em lei, sem prejuízo da ação penal cabível.","§ 5º A lei estabelecerá os prazos de prescrição para ilícitos praticados por qualquer agente, servidor ou não, que causem prejuízos ao erário, ressalvadas as respectivas ações de ressarcimento.","§ 6º As pessoas jurídicas de direito público e as de direito privado prestadoras de serviços públicos responderão pelos danos que seus agentes, nessa qualidade, causarem a terceiros, assegurado o direito de regresso contra o responsável nos casos de dolo ou culpa.","§ 7º A lei disporá sobre os requisitos e as restrições ao ocupante de cargo ou emprego da administração direta e indireta que possibilite o acesso a informações privilegiadas. (Parágrafo acrescido pela Emenda Constitucional nº 19, de 1998)","§ 8º A autonomia gerencial, orçamentária e financeira dos órgãos e entidades da administração direta e indireta poderá ser ampliada mediante contrato, a ser firmado entre seus administradores e o poder público, que tenha por objeto a fixação de metas de desempenho para o órgão ou entidade, cabendo à lei dispor sobre:","I - o prazo de duração do contrato;","II - os controles e critérios de avaliação de desempenho, direitos, obrigações e responsabilidade dos dirigentes;","III - a remuneração do pessoal. (Parágrafo acrescido pela Emenda Constitucional nº 19, de 1998)","§ 9º O disposto no inciso XI aplica-se às empresas públicas e às sociedades de economia mista, e suas subsidiárias, que receberem recursos da União, dos Estados, do Distrito Federal ou dos Municípios para pagamento de despesas de pessoal ou de custeio em geral. (Parágrafo acrescido pela Emenda Constitucional nº 19, de 1998)","§ 10. É vedada a percepção simultânea de proventos de aposentadoria decorrentes do art. 40 ou dos arts. 42 e 142 com a remuneração de cargo, emprego ou função pública, ressalvados os cargos acumuláveis na forma desta Constituição, os cargos eletivos e os cargos em comissão declarados em lei de livre nomeação e exoneração. (Parágrafo acrescido pela Emenda Constitucional nº 20, de 1998)","§ 11. Não serão computadas, para efeito dos limites remuneratórios de que trata o inciso XI do caput deste artigo, as parcelas de caráter indenizatório expressamente previstas em lei ordinária, aprovada pelo Congresso Nacional, de caráter nacional, aplicada a todos os Poderes e órgãos constitucionalmente autônomos. (Parágrafo acrescido pela Emenda Constitucional nº 47, de 2005, e com redação dada pela Emenda Constitucional nº 135, de 2024)","§ 12. Para os fins do disposto no inciso XI do caput deste artigo, fica facultado aos Estados e ao Distrito Federal fixar, em seu âmbito, mediante emenda às respectivas Constituições e Lei Orgânica, como limite único, o subsídio mensal dos Desembargadores do respectivo Tribunal de Justiça, limitado a noventa inteiros e vinte e cinco centésimos por cento do subsídio mensal dos Ministros do Supremo Tribunal Federal, não se aplicando o disposto neste parágrafo aos subsídios dos Deputados Estaduais e Distritais e dos Vereadores. (Parágrafo acrescido pela Emenda Constitucional nº 47, de 2005)","§ 13. O servidor público titular de cargo efetivo poderá ser readaptado para exercício de cargo cujas atribuições e responsabilidades sejam compatíveis com a limitação que tenha sofrido em sua capacidade física ou mental, enquanto permanecer nesta condição, desde que possua a habilitação e o nível de escolaridade exigidos para o cargo de destino, mantida a remuneração do cargo de origem. (Parágrafo acrescido pela Emenda Constitucional nº 103, de 2019)","§ 14. A aposentadoria concedida com a utilização de tempo de contribuição decorrente de cargo, emprego ou função pública, inclusive do Regime Geral de Previdência Social, acarretará o rompimento do vínculo que gerou o referido tempo de contribuição. (Parágrafo acrescido pela Emenda Constitucional nº 103, de 2019)","§ 15. É vedada a complementação de aposentadorias de servidores públicos e de pensões por morte a seus dependentes que não seja decorrente do disposto nos §§ 14 a 16 do art. 40 ou que não seja prevista em lei que extinga regime próprio de previdência social. (Parágrafo acrescido pela Emenda Constitucional nº 103, de 2019)","§ 16. Os órgãos e entidades da administração pública, individual ou conjuntamente, devem realizar avaliação das políticas públicas, inclusive com divulgação do objeto a ser avaliado e dos resultados alcançados, na forma da lei. (Parágrafo acrescido pela Emenda Constitucional nº 109, de 2021)","§ 17. (Vide Emenda Constitucional nº 132, de 2023)","§ 18. (Vide Emenda Constitucional nº 132, de 2023)"],"url":""},{"key":"l8429:1","law":"l8429","ref":"1","label":"Lei de Improbidade Administrativa · Art. 1","paragraphs":["Art. 1º O sistema de responsabilização por atos de improbidade administrativa tutelará a probidade na organização do Estado e no exercício de suas funções, como forma de assegurar a integridade do patrimônio público e social, nos termos desta Lei. (“Caput” do artigo com redação dada pela Lei nº 14.230, de 25/10/2021)","Parágrafo único. ( Revogado pela Lei nº 14.230, de 25/10/2021)","§ 1º Consideram-se atos de improbidade administrativa as condutas dolosas tipificadas nos arts. 9º, 10 e 11 desta Lei, ressalvados tipos previstos em leis especiais. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 2º Considera-se dolo a vontade livre e consciente de alcançar o resultado ilícito tipificado nos arts. 9º, 10 e 11 desta Lei, não bastando a voluntariedade do agente. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 3º O mero exercício da função ou desempenho de competências públicas, sem comprovação de ato doloso com fim ilícito, afasta a responsabilidade por ato de improbidade administrativa. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 4º Aplicam-se ao sistema da improbidade disciplinado nesta Lei os princípios constitucionais do direito administrativo sancionador. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 5º Os atos de improbidade violam a probidade na organização do Estado e no exercício de suas funções e a integridade do patrimônio público e social dos Poderes Executivo, Legislativo e Judiciário, bem como da administração direta e indireta, no âmbito da União, dos Estados, dos Municípios e do Distrito Federal. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 6º Estão sujeitos às sanções desta Lei os atos de improbidade praticados contra o patrimônio de entidade privada que receba subvenção, benefício ou incentivo, fiscal ou creditício, de entes públicos ou governamentais, previstos no § 5º deste artigo. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 7º Independentemente de integrar a administração indireta, estão sujeitos às sanções desta Lei os atos de improbidade praticados contra o patrimônio de entidade privada para cuja criação ou custeio o erário haja concorrido ou concorra no seu patrimônio ou receita atual, limitado o ressarcimento de prejuízos, nesse caso, à repercussão do ilícito sobre a contribuição dos cofres públicos. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 8º Não configura improbidade a ação ou omissão decorrente de divergência interpretativa da lei, baseada em jurisprudência, ainda que não pacificada, mesmo que não venha a ser posteriormente prevalecente nas decisões dos órgãos de controle ou dos tribunais do Poder Judiciário. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)"],"url":""},{"key":"l8429:2","law":"l8429","ref":"2","label":"Lei de Improbidade Administrativa · Art. 2","paragraphs":["Art. 2º Para os efeitos desta Lei, consideram-se agente público o agente político, o servidor público e todo aquele que exerce, ainda que transitoriamente ou sem remuneração, por eleição, nomeação, designação, contratação ou qualquer outra forma de investidura ou vínculo, mandato, cargo, emprego ou função nas entidades referidas no art. 1º desta Lei . (“Caput” do artigo com redação dada pela Lei nº 14.230, de 25/10/2021)","Parágrafo único. No que se refere a recursos de origem pública, sujeita-se às sanções previstas nesta Lei o particular, pessoa física ou jurídica, que celebra com a administração pública convênio, contrato de repasse, contrato de gestão, termo de parceria, termo de cooperação ou ajuste administrativo equivalente. ( Parágrafo único acrescido pela Lei nº 14.230, de 25/10/2021)"],"url":""},{"key":"l8429:3","law":"l8429","ref":"3","label":"Lei de Improbidade Administrativa · Art. 3","paragraphs":["Art. 3º As disposições desta Lei são aplicáveis, no que couber, àquele que, mesmo não sendo agente público, induza ou concorra dolosamente para a prática do ato de improbidade. (“Caput” do artigo com redação dada pela Lei nº 14.230, de 25/10/2021)","§ 1º Os sócios, os cotistas, os diretores e os colaboradores de pessoa jurídica de direito privado não respondem pelo ato de improbidade que venha a ser imputado à pessoa jurídica, salvo se, comprovadamente, houver participação e benefícios diretos, caso em que responderão nos limites da sua participação. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 2º As sanções desta Lei não se aplicarão à pessoa jurídica, caso o ato de improbidade administrativa seja também sancionado como ato lesivo à administração pública de que trata a Lei nº 12.846, de 1º de agosto de 2013. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","Art s . 4º a 6º ( Revogados pela Lei nº 14.230, de 25/10/2021)"],"url":""},{"key":"l8429:8","law":"l8429","ref":"8","label":"Lei de Improbidade Administrativa · Art. 8","paragraphs":["Art. 8º O sucessor ou o herdeiro daquele que causar dano ao erário ou que se enriquecer ilicitamente estão sujeitos apenas à obrigação de repará-lo até o limite do valor da herança ou do patrimônio transferido. ( A rtigo com redação dada pela Lei nº 14.230, de 25/10/2021)"],"url":""},{"key":"l8429:8-A","law":"l8429","ref":"8-A","label":"Lei de Improbidade Administrativa · Art. 8-A","paragraphs":["Art. 8º- A A responsabilidade sucessória de que trata o art. 8º desta Lei aplica-se também na hipótese de alteração contratual, de transformação, de incorporação, de fusão ou de cisão societária.","Parágrafo único. Nas hipóteses de fusão e de incorporação, a responsabilidade da sucessora será restrita à obrigação de reparação integral do dano causado, até o limite do patrimônio transferido, não lhe sendo aplicáveis as demais sanções previstas nesta Lei decorrentes de atos e de fatos ocorridos antes da data da fusão ou da incorporação, exceto no caso de simulação ou de evidente intuito de fraude, devidamente comprovados. ( Artigo acrescido pela Lei nº 14.230, de 25/10/2021)"],"url":""},{"key":"l8429:12","law":"l8429","ref":"12","label":"Lei de Improbidade Administrativa · Art. 12","paragraphs":["Art. 12. Independentemente do ressarcimento integral do dano patrimonial, se efetivo, e das sanções penais comuns e de responsabilidade, civis e administrativas previstas na legislação específica, está o responsável pelo ato de improbidade sujeito às seguintes cominações, que podem ser aplicadas isolada ou cumulativamente, de acordo com a gravidade do fato: (“Caput” do artigo com redação dada pela Lei nº 14.230, de 25/10/2021)","I - na hipótese do art. 9º desta Lei, perda dos bens ou valores acrescidos ilicitamente ao patrimônio, perda da função pública, suspensão dos direitos políticos até 14 (catorze) anos, pagamento de multa civil equivalente ao valor do acréscimo patrimonial e proibição de contratar com o poder público ou de receber benefícios ou incentivos fiscais ou creditícios, direta ou indiretamente, ainda que por intermédio de pessoa jurídica da qual seja sócio majoritário, pelo prazo não superior a 14 (catorze) anos; ( Incis o com redação dada pela Lei nº 14.230, de 25/10/2021)","II - na hipótese do art. 10 desta Lei, perda dos bens ou valores acrescidos ilicitamente ao patrimônio, se concorrer esta circunstância, perda da função pública, suspensão dos direitos políticos até 12 (doze) anos, pagamento de multa civil equivalente ao valor do dano e proibição de contratar com o poder público ou de receber benefícios ou incentivos fiscais ou creditícios, direta ou indiretamente, ainda que por intermédio de pessoa jurídica da qual seja sócio majoritário, pelo prazo não superior a 12 (doze) anos; ( Incis o com redação dada pela Lei nº 14.230, de 25/10/2021)","III - na hipótese do art. 11 desta Lei, pagamento de multa civil de até 24 (vinte e quatro) vezes o valor da remuneração percebida pelo agente e proibição de contratar com o poder público ou de receber benefícios ou incentivos fiscais ou creditícios, direta ou indiretamente, ainda que por intermédio de pessoa jurídica da qual seja sócio majoritário, pelo prazo não superior a 4 (quatro) anos; ( Incis o com redação dada pela Lei nº 14.230, de 25/10/2021)","IV - ( Inciso acrescido pela Lei complementar nº 157, de 29/12/2016 , e revogado pela Lei nº 14.230, de 25/10/2021)","Parágrafo único. (Revogado pela Lei nº 14.230, de 25/10/2021)","§ 1º A sanção de perda da função pública, nas hipóteses dos incisos I e II do caput deste artigo, atinge apenas o vínculo de mesma qualidade e natureza que o agente público ou político detinha com o poder público na época do cometimento da infração, podendo o magistrado, na hipótese do inciso I do caput deste artigo, e em caráter excepcional, estendê-la aos demais vínculos, consideradas as circunstâncias do caso e a gravidade da infração. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 2º A multa pode ser aumentada até o dobro, se o juiz considerar que, em virtude da situação econômica do réu, o valor calculado na forma dos incisos I, II e III do caput deste artigo é ineficaz para reprovação e prevenção do ato de improbidade. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 3º Na responsabilização da pessoa jurídica, deverão ser considerados os efeitos econômicos e sociais das sanções, de modo a viabilizar a manutenção de suas atividades. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 4º Em caráter excepcional e por motivos relevantes devidamente justificados, a sanção de proibição de contratação com o poder público pode extrapolar o ente público lesado pelo ato de improbidade, observados os impactos econômicos e sociais das sanções, de forma a preservar a função social da pessoa jurídica, conforme disposto no § 3º deste artigo. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 5º No caso de atos de menor ofensa aos bens jurídicos tutelados por esta Lei, a sanção limitar-se-á à aplicação de multa, sem prejuízo do ressarcimento do dano e da perda dos valores obtidos, quando for o caso, nos termos do caput deste artigo. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 6º Se ocorrer lesão ao patrimônio público, a reparação do dano a que se refere esta Lei deverá deduzir o ressarcimento ocorrido nas instâncias criminal, civil e administrativa que tiver por objeto os mesmos fatos. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 7º As sanções aplicadas a pessoas jurídicas com base nesta Lei e na Lei nº 12.846, de 1º de agosto de 2013, deverão observar o princípio constitucional do non bis in idem . ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 8º A sanção de proibição de contratação com o poder público deverá constar do Cadastro Nacional de Empresas Inidôneas e Suspensas (CEIS) de que trata a Lei nº 12.846, de 1º de agosto de 2013, observadas as limitações territoriais contidas em decisão judicial, conforme disposto no § 4º deste artigo. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 9º As sanções previstas neste artigo somente poderão ser executadas após o trânsito em julgado da sentença condenatória. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 10. Para efeitos de contagem do prazo da sanção de suspensão dos direitos políticos, computar-se-á retroativamente o intervalo de tempo entre a decisão colegiada e o trânsito em julgado da sentença condenatória. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)"],"url":""},{"key":"l8429:17-C","law":"l8429","ref":"17-C","label":"Lei de Improbidade Administrativa · Art. 17-C","paragraphs":["Art. 17-C. A sentença proferida nos processos a que se refere esta Lei deverá, além de observar o disposto no art. 489 da Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil):","I - indicar de modo preciso os fundamentos que demonstram os elementos a que se referem os arts. 9º, 10 e 11 desta Lei, que não podem ser presumidos;","II - considerar as consequências práticas da decisão, sempre que decidir com base em valores jurídicos abstratos;","III - considerar os obstáculos e as dificuldades reais do gestor e as exigências das políticas públicas a seu cargo, sem prejuízo dos direitos dos administrados e das circunstâncias práticas que houverem imposto, limitado ou condicionado a ação do agente;","IV - considerar, para a aplicação das sanções, de forma isolada ou cumulativa:","a) os princípios da proporcionalidade e da razoabilidade;","b) a natureza, a gravidade e o impacto da infração cometida;","c) a extensão do dano causado;","d) o proveito patrimonial obtido pelo agente;","e) as circunstâncias agravantes ou atenuantes;","f) a atuação do agente em minorar os prejuízos e as consequências advindas de sua conduta omissiva ou comissiva;","g) os antecedentes do agente;","V - considerar na aplicação das sanções a dosimetria das sanções relativas ao mesmo fato já aplicadas ao agente;","VI - considerar, na fixação das penas relativamente ao terceiro, quando for o caso, a sua atuação específica, não admitida a sua responsabilização por ações ou omissões para as quais não tiver concorrido ou das quais não tiver obtido vantagens patrimoniais indevidas;","VII - indicar, na apuração da ofensa a princípios, critérios objetivos que justifiquem a imposição da sanção.","§ 1º A ilegalidade sem a presença de dolo que a qualifique não configura ato de improbidade.","§ 2º Na hipótese de litisconsórcio passivo, a condenação ocorrerá no limite da participação e dos benefícios diretos, vedada qualquer solidariedade.","§ 3º Não haverá remessa necessária nas sentenças de que trata esta Lei. ( Artigo acrescido pela Lei nº 14.230, de 25/10/2021)"],"url":""},{"key":"l8429:16","law":"l8429","ref":"16","label":"Lei de Improbidade Administrativa · Art. 16","paragraphs":["Art. 16. Na ação por improbidade administrativa poderá ser formulado, em caráter antecedente ou incidente, pedido de indisponibilidade de bens dos réus, a fim de garantir a integral recomposição do erário ou do acréscimo patrimonial resultante de enriquecimento ilícito. (“Caput” do artigo com redação dada pela Lei nº 14.230, de 25/10/2021)","§ 1º (Revogado pela Lei nº 14.230, de 25/10/2021)","§ 1º-A O pedido de indisponibilidade de bens a que se refere o caput deste artigo poderá ser formulado independentemente da representação de que trata o art. 7º desta Lei. ( Parágraf o acrescido pela Lei nº 14.230, de 25/10/2021)","§ 2º Quando for o caso, o pedido de indisponibilidade de bens a que se refere o caput deste artigo incluirá a investigação, o exame e o bloqueio de bens, contas bancárias e aplicações financeiras mantidas pelo indiciado no exterior, nos termos da lei e dos tratados internacionais. ( Parágraf o com redação dada pela Lei nº 14.230, de 25/10/2021)","§ 3º O pedido de indisponibilidade de bens a que se refere o caput deste artigo apenas será deferido mediante a demonstração no caso concreto de perigo de dano irreparável ou de risco ao resultado útil do processo, desde que o juiz se convença da probabilidade da ocorrência dos atos descritos na petição inicial com fundamento nos respectivos elementos de instrução, após a oitiva do réu em 5 (cinco) dias. ( Parágraf o acrescido pela Lei nº 14.230, de 25/10/2021)","§ 4º A indisponibilidade de bens poderá ser decretada sem a oitiva prévia do réu, sempre que o contraditório prévio puder comprovadamente frustrar a efetividade da medida ou houver outras circunstâncias que recomendem a proteção liminar, não podendo a urgência ser presumida. ( Parágraf o acrescido pela Lei nº 14.230, de 25/10/2021)","§ 5º Se houver mais de um réu na ação, a somatória dos valores declarados indisponíveis não poderá superar o montante indicado na petição inicial como dano ao erário ou como enriquecimento ilícito. ( Parágraf o acrescido pela Lei nº 14.230, de 25/10/2021)","§ 6º O valor da indisponibilidade considerará a estimativa de dano indicada na petição inicial, permitida a sua substituição por caução idônea, por fiança bancária ou por seguro-garantia judicial, a requerimento do réu, bem como a sua readequação durante a instrução do processo. ( Parágraf o acrescido pela Lei nº 14.230, de 25/10/2021)","§ 7º A indisponibilidade de bens de terceiro dependerá da demonstração da sua efetiva concorrência para os atos ilícitos apurados ou, quando se tratar de pessoa jurídica, da instauração de incidente de desconsideração da personalidade jurídica, a ser processado na forma da lei processual. ( Parágraf o acrescido pela Lei nº 14.230, de 25/10/2021)","§ 8º Aplica-se à indisponibilidade de bens regida por esta Lei, no que for cabível, o regime da tutela provisória de urgência da Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil). ( Parágraf o acrescido pela Lei nº 14.230, de 25/10/2021)","§ 9º Da decisão que deferir ou indeferir a medida relativa à indisponibilidade de bens caberá agravo de instrumento, nos termos da Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil). ( Parágraf o acrescido pela Lei nº 14.230, de 25/10/2021)","§ 10. A indisponibilidade recairá sobre bens que assegurem exclusivamente o integral ressarcimento do dano ao erário, sem incidir sobre os valores a serem eventualmente aplicados a título de multa civil ou sobre acréscimo patrimonial decorrente de atividade lícita. ( Parágraf o acrescido pela Lei nº 14.230, de 25/10/2021)","§ 11. A ordem de indisponibilidade de bens deverá priorizar veículos de via terrestre, bens imóveis, bens móveis em geral, semoventes, navios e aeronaves, ações e quotas de sociedades simples e empresárias, pedras e metais preciosos e, apenas na inexistência desses, o bloqueio de contas bancárias, de forma a garantir a subsistência do acusado e a manutenção da atividade empresária ao longo do processo. ( Parágraf o acrescido pela Lei nº 14.230, de 25/10/2021)","§ 12. O juiz, ao apreciar o pedido de indisponibilidade de bens do réu a que se refere o caput deste artigo, observará os efeitos práticos da decisão, vedada a adoção de medida capaz de acarretar prejuízo à prestação de serviços públicos. ( Parágraf o acrescido pela Lei nº 14.230, de 25/10/2021)","§ 13. É vedada a decretação de indisponibilidade da quantia de até 40 (quarenta) salários mínimos depositados em caderneta de poupança, em outras aplicações financeiras ou em conta-corrente. ( Parágraf o acrescido pela Lei nº 14.230, de 25/10/2021)","§ 14. É vedada a decretação de indisponibilidade do bem de família do réu, salvo se comprovado que o imóvel seja fruto de vantagem patrimonial indevida, conforme descrito no art. 9º desta Lei. ( Parágraf o acrescido pela Lei nº 14.230, de 25/10/2021)"],"url":""},{"key":"l8429:17","law":"l8429","ref":"17","label":"Lei de Improbidade Administrativa · Art. 17","paragraphs":["Art. 17. A ação para a aplicação das sanções de que trata esta Lei será proposta pelo Ministério Público e seguirá o procedimento comum previsto na Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil), salvo o disposto nesta Lei. (“Caput” do artigo com redação dada pela Lei nº 14.230, de 25/10/2021) (Vide ADIs nºs 7.042 e 7.043/2021 )","§ 1º (Revogado pela Lei nº 14.230, de 25/10/2021)","§ 2º (Revogado pela Lei nº 14.230, de 25/10/2021)","§ 3º (Revogado pela Lei nº 14.230, de 25/10/2021)","§ 4º (Revogado pela Lei nº 14.230, de 25/10/2021)","§ 4º-A A ação a que se refere o caput deste artigo deverá ser proposta perante o foro do local onde ocorrer o dano ou da pessoa jurídica prejudicada. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 5º A propositura da ação a que se refere o caput deste artigo prevenirá a competência do juízo para todas as ações posteriormente intentadas que possuam a mesma causa de pedir ou o mesmo objeto. (Parágrafo acrescido pela Medida Provisória nº 2.180-35, de 24/8/2001 , e com nova redação dada pela Lei nº 14.230, de 25/10/2021)","§ 6º A petição inicial observará o seguinte: (Parágrafo acrescido pela Medida Provisória nº 2.225-45, de 4/9/2001 , e com nova redação dada pela Lei nº 14.230, de 25/10/2021)","I - deverá individualizar a conduta do réu e apontar os elementos probatórios mínimos que demonstrem a ocorrência das hipóteses dos arts. 9º, 10 e 11 desta Lei e de sua autoria, salvo impossibilidade devidamente fundamentada; ( Inciso acrescido pela Lei nº 14.230, de 25/10/2021)","II - será instruída com documentos ou justificação que contenham indícios suficientes da veracidade dos fatos e do dolo imputado ou com razões fundamentadas da impossibilidade de apresentação de qualquer dessas provas, observada a legislação vigente, inclusive as disposições constantes dos arts. 77 e 80 da Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil). ( Inciso acrescido pela Lei nº 14.230, de 25/10/2021)","§ 6º-A O Ministério Público poderá requerer as tutelas provisórias adequadas e necessárias, nos termos dos arts. 294 a 310 da Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil). ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021) (Vide ADIs nºs 7.042 e 7.043/2021 )","§ 6º-B A petição inicial será rejeitada nos casos do art. 330 da Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil), bem como quando não preenchidos os requisitos a que se referem os incisos I e II do § 6º deste artigo, ou ainda quando manifestamente inexistente o ato de improbidade imputado. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 7º Se a petição inicial estiver em devida forma, o juiz mandará autuá-la e ordenará a citação dos requeridos para que a contestem no prazo comum de 30 (trinta) dias, iniciado o prazo na forma do art. 231 da Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil). (Parágrafo acrescido pela Medida Provisória nº 2.225-45, de 4/9/2001 , e com nova redação dada pela Lei nº 14.230, de 25/10/2021)","§ 8º (Parágrafo acrescido pela Medida Provisória nº 2.225-45, de 4/9/2001 , e revogado pela Lei nº 14.230, de 25/10/2021)","§ 9º (Parágrafo acrescido pela Medida P r ovisória nº 2.225-45, de 4/9/2001 , e revogado pela Lei nº 14.230, de 25/10/2021)","§ 9º-A Da decisão que rejeitar questões preliminares suscitadas pelo réu em sua contestação caberá agravo de instrumento. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 10. (Parágrafo acrescido pela Medida Provisória nº 2.225-45, de 4/9/2001 , e revogado pela Lei nº 14.230, de 25/10/2021)","§ 10-A. Havendo a possibilidade de solução consensual, poderão as partes requerer ao juiz a interrupção do prazo para a contestação, por prazo não superior a 90 (noventa) dias. ( Inciso acrescido pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)","§ 10-B. Oferecida a contestação e, se for o caso, ouvido o autor, o juiz:","I - procederá ao julgamento conforme o estado do processo, observada a eventual inexistência manifesta do ato de improbidade;","II - poderá desmembrar o litisconsórcio, com vistas a otimizar a instrução processual. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 10-C. Após a réplica do Ministério Público, o juiz proferirá decisão na qual indicará com precisão a tipificação do ato de improbidade administrativa imputável ao réu, sendo - lhe vedado modificar o fato principal e a capitulação legal apresentada pelo autor. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021) (Vide ADIs nºs 7.042 e 7.043/2021 )","§ 10-D. Para cada ato de improbidade administrativa, deverá necessariamente ser indicado apenas um tipo dentre aqueles previstos nos arts. 9º, 10 e 11 desta Lei. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 10-E. Proferida a decisão referida no § 10-C deste artigo, as partes serão intimadas a especificar as provas que pretendem produzir. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 10-F. Será nula a decisão de mérito total ou parcial da ação de improbidade administrativa que:","I - condenar o requerido por tipo diverso daquele definido na petição inicial;","II - condenar o requerido sem a produção das provas por ele tempestivamente especificadas. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 11. Em qualquer momento do processo, verificada a inexistência do ato de improbidade, o juiz julgará a demanda improcedente. (Parágrafo acrescido pela Medida Provisória nº 2.225-45, de 4/9/2001 , e com nova redação dada pela Lei nº 14.230, de 25/10/2021)","§ 12. (Parágrafo acrescido pela Medida Provisória nº 2.225-45, de 4/9/2001 , e revogado pela Lei nº 14.230, de 25/10/2021)","§ 13. ( Parágrafo acrescido pela Lei Complementar nº 157, de 29/12/2016 , e revogado pela Lei nº 14.230, de 25/10/2021)","§ 14. Sem prejuízo da citação dos réus, a pessoa jurídica interessada será intimada para, caso queira, intervir no processo. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 15. Se a imputação envolver a desconsideração de pessoa jurídica, serão observadas as regras previstas nos arts. 133, 134, 135, 136 e 137 da Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil). ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 16. A qualquer momento, se o magistrado identificar a existência de ilegalidades ou de irregularidades administrativas a serem sanadas sem que estejam presentes todos os requisitos para a imposição das sanções aos agentes incluídos no polo passivo da demanda, poderá, em decisão motivada, converter a ação de improbidade administrativa em ação civil pública, regulada pela Lei nº 7.347, de 24 de julho de 1985. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 17. Da decisão que converter a ação de improbidade em ação civil pública caberá agravo de instrumento. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 18. Ao réu será assegurado o direito de ser interrogado sobre os fatos de que trata a ação, e a sua recusa ou o seu silêncio não implicarão confissão. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 19. Não se aplicam na ação de improbidade administrativa:","I - a presunção de veracidade dos fatos alegados pelo autor em caso de revelia;","II - a imposição de ônus da prova ao réu, na forma dos §§ 1º e 2º do art. 373 da Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil);","III - o ajuizamento de mais de uma ação de improbidade administrativa pelo mesmo fato, competindo ao Conselho Nacional do Ministério Público dirimir conflitos de atribuições entre membros de Ministérios Públicos distintos;","IV - o reexame obrigatório da sentença de improcedência ou de extinção sem resolução de mérito. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 20. A assessoria jurídica que emitiu o parecer atestando a legalidade prévia dos atos administrativos praticados pelo administrador público ficará obrigada a defendê-lo judicialmente, caso este venha a responder ação por improbidade administrativa, até que a decisão transite em julgado. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021) (Vide ADIs nºs 7.042 e 7.043/2021 )","§ 21. Das decisões interlocutórias caberá agravo de instrumento, inclusive da decisão que rejeitar questões preliminares suscitadas pelo réu em sua contestação. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)"],"url":""},{"key":"l8429:17-D","law":"l8429","ref":"17-D","label":"Lei de Improbidade Administrativa · Art. 17-D","paragraphs":["Art. 17-D. A ação por improbidade administrativa é repressiva, de caráter sancionatório, destinada à aplicação de sanções de caráter pessoal previstas nesta Lei, e não constitui ação civil, vedado seu ajuizamento para o controle de legalidade de políticas públicas e para a proteção do patrimônio público e social, do meio ambiente e de outros interesses difusos, coletivos e individuais homogêneos.","Parágrafo único. Ressalvado o disposto nesta Lei, o controle de legalidade de políticas públicas e a responsabilidade de agentes públicos, inclusive políticos, entes públicos e governamentais, por danos ao meio ambiente, ao consumidor, a bens e direitos de valor artístico, estético, histórico, turístico e paisagístico, a qualquer outro interesse difuso ou coletivo, à ordem econômica, à ordem urbanística, à honra e à dignidade de grupos raciais, étnicos ou religiosos e ao patrimônio público e social submetem-se aos termos da Lei nº 7.347, de 24 de julho de 1985. ( Artigo acrescido pela Lei nº 14.230, de 25/10/2021)"],"url":""},{"key":"l8429:23","law":"l8429","ref":"23","label":"Lei de Improbidade Administrativa · Art. 23","paragraphs":["Art. 23. A ação para a aplicação das sanções previstas nesta Lei prescreve em 8 (oito) anos, contados a partir da ocorrência do fato ou, no caso de infrações permanentes, do dia em que cessou a permanência. ( “Caput” do artigo com redação dada pela Lei nº 14.230, de 25/10/2021)","I - (Revogado pela Lei nº 14.230, de 25/10/2021)","II - (Revogado pela Lei nº 14.230, de 25/10/2021)","III - ( Inciso acrescido pela Lei nº 13.019, de 31/7/2014 , e revogado pela Lei nº 14.230, de 25/10/2021)","§ 1º A instauração de inquérito civil ou de processo administrativo para apuração dos ilícitos referidos nesta Lei suspende o curso do prazo prescricional por, no máximo, 180 (cento e oitenta) dias corridos, recomeçando a correr após a sua conclusão ou, caso não concluído o processo, esgotado o prazo de suspensão. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 2º O inquérito civil para apuração do ato de improbidade será concluído no prazo de 365 (trezentos e sessenta e cinco) dias corridos, prorrogável uma única vez por igual período, mediante ato fundamentado submetido à revisão da instância competente do órgão ministerial, conforme dispuser a respectiva lei orgânica. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 3º Encerrado o prazo previsto no § 2º deste artigo, a ação deverá ser proposta no prazo de 30 (trinta) dias, se não for caso de arquivamento do inquérito civil. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 4º O prazo da prescrição referido no caput deste artigo interrompe-se:","I - pelo ajuizamento da ação de improbidade administrativa;","II - pela publicação da sentença condenatória;","III - pela publicação de decisão ou acórdão de Tribunal de Justiça ou Tribunal Regional Federal que confirma sentença condenatória ou que reforma sentença de improcedência;","IV - pela publicação de decisão ou acórdão do Superior Tribunal de Justiça que confirma acórdão condenatório ou que reforma acórdão de improcedência;","V - pela publicação de decisão ou acórdão do Supremo Tribunal Federal que confirma acórdão condenatório ou que reforma acórdão de improcedência. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 5º Interrompida a prescrição, o prazo recomeça a correr do dia da interrupção, pela metade do prazo previsto no caput deste artigo. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 6º A suspensão e a interrupção da prescrição produzem efeitos relativamente a todos os que concorreram para a prática do ato de improbidade. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 7º Nos atos de improbidade conexos que sejam objeto do mesmo processo, a suspensão e a interrupção relativas a qualquer deles estendem-se aos demais. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 8º O juiz ou o tribunal, depois de ouvido o Ministério Público, deverá, de ofício ou a requerimento da parte interessada, reconhecer a prescrição intercorrente da pretensão sancionadora e decretá-la de imediato, caso, entre os marcos interruptivos referidos no § 4º, transcorra o prazo previsto no § 5º deste artigo. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)"],"url":""},{"key":"l8429:17-B","law":"l8429","ref":"17-B","label":"Lei de Improbidade Administrativa · Art. 17-B","paragraphs":["Art. 17-B. O Ministério Público poderá, conforme as circunstâncias do caso concreto, celebrar acordo de não persecução civil, desde que dele advenham, ao menos, os seguintes resultados: (Vide ADIs nºs 7.042 e 7.043/2021 )","I - o integral ressarcimento do dano;","II - a reversão à pessoa jurídica lesada da vantagem indevida obtida, ainda que oriunda de agentes privados.","§ 1º A celebração do acordo a que se refere o caput deste artigo dependerá, cumulativamente:","I - da oitiva do ente federativo lesado, em momento anterior ou posterior à propositura da ação;","II - de aprovação, no prazo de até 60 (sessenta) dias, pelo órgão do Ministério Público competente para apreciar as promoções de arquivamento de inquéritos civis, se anterior ao ajuizamento da ação;","III - de homologação judicial, independentemente de o acordo ocorrer antes ou depois do ajuizamento da ação de improbidade administrativa.","§ 2º Em qualquer caso, a celebração do acordo a que se refere o caput deste artigo considerará a personalidade do agente, a natureza, as circunstâncias, a gravidade e a repercussão social do ato de improbidade, bem como as vantagens, para o interesse público, da rápida solução do caso.","§ 3º Para fins de apuração do valor do dano a ser ressarcido, deverá ser realizada a oitiva do Tribunal de Contas competente, que se manifestará, com indicação dos parâmetros utilizados, no prazo de 90 (noventa) dias.","§ 4º O acordo a que se refere o caput deste artigo poderá ser celebrado no curso da investigação de apuração do ilícito, no curso da ação de improbidade ou no momento da execução da sentença condenatória.","§ 5º As negociações para a celebração do acordo a que se refere o caput deste artigo ocorrerão entre o Ministério Público, de um lado, e, de outro, o investigado ou demandado e o seu defensor. (Vide ADIs nºs 7.042 e 7.043/2021 )","§ 6º O acordo a que se refere o caput deste artigo poderá contemplar a adoção de mecanismos e procedimentos internos de integridade, de auditoria e de incentivo à denúncia de irregularidades e a aplicação efetiva de códigos de ética e de conduta no âmbito da pessoa jurídica, se for o caso, bem como de outras medidas em favor do interesse público e de boas práticas administrativas.","§ 7º Em caso de descumprimento do acordo a que se refere o caput deste artigo, o investigado ou o demandado ficará impedido de celebrar novo acordo pelo prazo de 5 (cinco) anos, contado do conhecimento pelo Ministério Público do efetivo descumprimento. (Vide ADIs nºs 7.042 e 7.043/2021 ) ( Artigo acrescido pela Lei nº 14.230, de 25/10/2021)"],"url":""},{"key":"l8429:21","law":"l8429","ref":"21","label":"Lei de Improbidade Administrativa · Art. 21","paragraphs":["Art. 21. A aplicação das sanções previstas nesta Lei independe:","I - da efetiva ocorrência de dano ao patrimônio público, salvo quanto à pena de ressarcimento e às condutas previstas no art. 10 desta Lei; ( Inciso com redação dada pela Lei nº 14.230, de 25/10/2021)","II - da aprovação ou rejeição das contas pelo órgão de controle interno ou pelo Tribunal ou Conselho de Contas.","§ 1º Os atos do órgão de controle interno ou externo serão considerados pelo juiz quando tiverem servido de fundamento para a conduta do agente público. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 2º As provas produzidas perante os órgãos de controle e as correspondentes decisões deverão ser consideradas na formação da convicção do juiz, sem prejuízo da análise acerca do dolo na conduta do agente. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 3º As sentenças civis e penais produzirão efeitos em relação à ação de improbidade quando concluírem pela inexistência da conduta ou pela negativa da autoria. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 4º A absolvição criminal em ação que discuta os mesmos fatos, confirmada por decisão colegiada, impede o trâmite da ação da qual trata esta Lei, havendo comunicação com todos os fundamentos de absolvição previstos no art. 386 do Decreto-Lei nº 3.689, de 3 de outubro de 1941 (Código de Processo Penal). ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)","§ 5º Sanções eventualmente aplicadas em outras esferas deverão ser compensadas com as sanções aplicadas nos termos desta Lei. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)"],"url":""},{"key":"cpp:65","law":"cpp","ref":"65","label":"Código de Processo Penal · Art. 65","paragraphs":["Art. 65. Faz coisa julgada no cível a sentença penal que reconhecer ter sido o ato praticado em estado de necessidade, em legítima defesa, em estrito cumprimento de dever legal ou no exercício regular de direito. (Vide ADPF nº 779/2021)"],"url":""},{"key":"cpp:386","law":"cpp","ref":"386","label":"Código de Processo Penal · Art. 386","paragraphs":["Art. 386. O juiz absolverá o réu, mencionando a causa na parte dispositiva, desde que reconheça:","I - estar provada a inexistência do fato;","II - não haver prova da existência do fato;","III - não constituir o fato infração penal;","IV - estar provado que o réu não concorreu para a infração penal; (Inciso com redação dada pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","V - não existir prova de ter o réu concorrido para a infração penal; (Inciso com redação dada pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","VI - existirem circunstâncias que excluam o crime ou isentem o réu de pena (arts. 20, 21, 22, 23, 26 e § 1º do art. 28, todos do Código Penal), ou mesmo se houver fundada dúvida sobre sua existência; (Inciso com redação dada pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","VII - não existir prova suficiente para a condenação. (Inciso acrescido pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","Parágrafo único. Na sentença absolutória, o juiz:","I - mandará, se for o caso, pôr o réu em liberdade;","II - ordenará a cessação das medidas cautelares e provisoriamente aplicadas; (Inciso com redação dada pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","III - aplicará medida de segurança, se cabível."],"url":""},{"key":"l8429:20","law":"l8429","ref":"20","label":"Lei de Improbidade Administrativa · Art. 20","paragraphs":["Art. 20. A perda da função pública e a suspensão dos direitos políticos só se efetivam com o trânsito em julgado da sentença condenatória.","§ 1º A autoridade judicial competente poderá determinar o afastamento do agente público do exercício do cargo, do emprego ou da função, sem prejuízo da remuneração, quando a medida for necessária à instrução processual ou para evitar a iminente prática de novos ilícitos. ( Parágrafo único transformado em § 1º, com redação dada pela Lei nº 14.230, de 25/10/2021)","§ 2º O afastamento previsto no § 1º deste artigo será de até 90 (noventa) dias, prorrogáveis uma única vez por igual prazo, mediante decisão motivada. ( Parágrafo acrescido pela Lei nº 14.230, de 25/10/2021)"],"url":""}];})(window);
